<script setup lang="ts">
import {pmsFetch} from './loading';
import PmsFormDialog from './PmsFormDialog.vue';
import PmsTableControls from './PmsTableControls.vue';
import {ref,onMounted,computed} from 'vue';const props=defineProps<{csrf?:string;permissions:string[]}>();const deletion=ref<any>(null),sortKey=ref('id'),ascending=ref(true);function sort(key:string){if(sortKey.value===key)ascending.value=!ascending.value;else{sortKey.value=key;ascending.value=true;}tablePage.value=1;}function sortValue(u:any,key:string){if(key==='departments')return u.departments.map((d:any)=>d.dept_name).join(', ');if(key==='roles')return u.roles.map((r:any)=>r.role_name).join(', ');return u[key]??'';}const search=ref(''),tablePage=ref(1),tableSize=ref(10);const paged=computed(()=>tableSize.value<0?shown.value:shown.value.slice((tablePage.value-1)*tableSize.value,tablePage.value*tableSize.value));const shown=computed(()=>data.value?.data?.filter((u:any)=>[u.id,u.name,u.email,sortValue(u,'departments'),sortValue(u,'roles'),Number(u.status)===1?'active':'inactive'].join(' ').toLowerCase().includes(search.value.toLowerCase())).sort((a:any,b:any)=>{const av=sortValue(a,sortKey.value),bv=sortValue(b,sortKey.value);return (typeof av==='number'?av-bv:String(av).localeCompare(String(bv)))*(ascending.value?1:-1);})||[]);const data=ref<any>(null),editor=ref<any>(null),busy=ref(false),error=ref(''),message=ref('');const can=(k:string)=>props.permissions.includes('*')||props.permissions.includes(k);
async function api(path='',method='GET',body?:any){const r=await pmsFetch('/pms/api/employees'+path,{method,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf||''},body:body?JSON.stringify(body):undefined});const d=await r.json();if(!r.ok)throw Error(Object.values(d.errors||{}).flat().join(' ')||d.message||'Unable to complete this action.');return d;}
async function load(){try{data.value=await api();}catch(e){error.value=(e as Error).message;}}
async function edit(row?:any){error.value='';if(!row){editor.value={name:'',surname:'',designation:'',email:'',password:'',status:1,dept_id:'',role_id:''};return;}busy.value=true;try{const d=(await api('/'+row.id)).data;editor.value={...d,status:Number(d.status)===1?1:2,dept_id:d.departments[0]?.id||'',role_id:d.roles[0]?.id||''};}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function remove(u:any){busy.value=true;error.value='';try{const r=await api('/'+u.id,'DELETE');message.value=r.message;deletion.value=null;await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function save(){busy.value=true;error.value='';try{const d=await api(editor.value.id?'/'+editor.value.id:'','POST',editor.value);message.value=d.message;editor.value=null;await load();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}onMounted(load);
</script>
<template><section class="pms-employees-screen"><p v-if="error&&!editor&&!deletion" class="notice admin-error" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p><PmsFormDialog v-if="editor" class="pms-employee-dialog" title="Employee" size="lg" centered @close="editor=null"><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><form id="pms-employee-form" class="pms-reference-form" @submit.prevent="save"><label>Name <span class="text-danger">*</span><input placeholder="Enter name" v-model="editor.name" required maxlength="255"></label><label>Surname<input placeholder="Enter surname" v-model="editor.surname" maxlength="255"></label><label>Email <span class="text-danger">*</span><input placeholder="Enter email" type="email" v-model="editor.email" required maxlength="255"></label><label v-if="!editor.id">Password <span class="text-danger">*</span><input placeholder="Enter Password" type="password" v-model="editor.password" required minlength="8" autocomplete="new-password"></label><label>Designation <span class="text-danger">*</span><input placeholder="Enter designation" v-model="editor.designation" required maxlength="255"></label><label>Role <span class="text-danger">*</span><select v-model.number="editor.role_id" required><option value="" disabled>Select role</option><option v-for="r in data?.roles" :key="r.id" :value="r.id">{{r.role_name}}</option></select></label><label>Department <span class="text-danger">*</span><select v-model.number="editor.dept_id" required><option value="" disabled>Select department</option><option v-for="d in data?.departments" :key="d.id" :value="d.id">{{d.dept_name}}</option></select></label><label>Status <span class="text-danger">*</span><select v-model.number="editor.status"><option :value="1">Active</option><option :value="2">Inactive</option></select></label></form><template #footer><button type="button" class="button pms-employee-close" @click="editor=null">Close</button><button form="pms-employee-form" class="button primary" :disabled="busy">{{busy?'Saving...':editor.id?'Update':'Create'}}</button></template></PmsFormDialog><div class="pms-table-card"><div class="pms-table-heading"><button v-if="can('employee-add')" class="button primary" @click="edit()"><i aria-hidden="true" class="ti ti-circle-plus"></i>Create</button></div><PmsTableControls :total="shown.length" v-model:page="tablePage" v-model:size="tableSize" v-model:search="search" search-placeholder="Search..." hide-search-label/><table class="pms-table"><thead><tr><th scope="col" :aria-sort="sortKey==='id'?(ascending?'ascending':'descending'):'none'"><button class="pms-employee-sort" @click="sort('id')">ID<span aria-hidden="true"><i class="ti ti-chevron-up"></i><i class="ti ti-chevron-down"></i></span></button></th><th scope="col">Image</th><th scope="col" :aria-sort="sortKey==='name'?(ascending?'ascending':'descending'):'none'"><button class="pms-employee-sort" @click="sort('name')">Name<span aria-hidden="true"><i class="ti ti-chevron-up"></i><i class="ti ti-chevron-down"></i></span></button></th><th scope="col" :aria-sort="sortKey==='email'?(ascending?'ascending':'descending'):'none'"><button class="pms-employee-sort" @click="sort('email')">Email<span aria-hidden="true"><i class="ti ti-chevron-up"></i><i class="ti ti-chevron-down"></i></span></button></th><th scope="col" :aria-sort="sortKey==='departments'?(ascending?'ascending':'descending'):'none'"><button class="pms-employee-sort" @click="sort('departments')">Department<span aria-hidden="true"><i class="ti ti-chevron-up"></i><i class="ti ti-chevron-down"></i></span></button></th><th scope="col" :aria-sort="sortKey==='roles'?(ascending?'ascending':'descending'):'none'"><button class="pms-employee-sort" @click="sort('roles')">Role<span aria-hidden="true"><i class="ti ti-chevron-up"></i><i class="ti ti-chevron-down"></i></span></button></th><th scope="col" :aria-sort="sortKey==='status'?(ascending?'ascending':'descending'):'none'"><button class="pms-employee-sort" @click="sort('status')">Status<span aria-hidden="true"><i class="ti ti-chevron-up"></i><i class="ti ti-chevron-down"></i></span></button></th><th scope="col">Actions</th></tr></thead><tbody><tr v-for="u in paged" :key="u.id"><td>{{u.id}}</td><td><img v-if="u.profile_img" class="pms-employee-avatar" :src="u.profile_img" alt=""><span v-else class="pms-employee-avatar">{{u.name.charAt(0)}}</span></td><td>{{u.name}}</td><td>{{u.email}}</td><td><span v-if="u.departments.length" class="badge bg-label-primary text-uppercase">{{u.departments[0].dept_name}}</span><span v-else class="text-muted">Not assigned</span></td><td><span v-if="u.roles.length" class="badge bg-label-info">{{u.roles[0].role_name}}</span><span v-else class="text-danger">No role</span></td><td><span class="badge text-uppercase" :class="Number(u.status)===1?'bg-label-success':'bg-label-danger'">{{Number(u.status)===1?'Active':'Inactive'}}</span></td><td><div class="pms-project-actions"><button v-if="can('employee-edit')" class="pms-icon-action action-edit" aria-label="Edit employee" @click="edit(u)"><i class="ti ti-edit"></i></button><button v-if="can('employee-trash')" class="pms-icon-action action-delete" aria-label="Delete employee" :disabled="busy" @click="deletion=u"><i class="ti ti-trash"></i></button></div></td></tr><tr v-if="!shown.length"><td colspan="8">No employees found.</td></tr></tbody></table><PmsTableControls footer :total="shown.length" v-model:page="tablePage" v-model:size="tableSize"/></div><PmsFormDialog v-if="deletion" class="pms-employee-delete-dialog" title="Are you sure?" size="sm" @close="deletion=null"><div class="pms-employee-delete-warning" aria-hidden="true">!</div><p>You won't be able to revert this!</p><p v-if="error" class="notice admin-error" role="alert">{{error}}</p><template #footer><button class="button pms-delete-confirm" :disabled="busy" @click="remove(deletion)">Yes, delete it!</button><button class="button pms-delete-cancel" :disabled="busy" @click="deletion=null">Cancel</button></template></PmsFormDialog></section></template>